import { courseCatalog as legacyCatalog } from '../legacyLessonContent';

// The six thematic sections form a spiral: known chunks return in a new task,
// then one additional language function is practised before consolidation.
const production = (writingPrompt, speakingPrompt, criteria) => ({ writingPrompt, speakingPrompt, criteria });
const reuse = (level, id, extra) => {
  const original = legacyCatalog[level].lessons.find((lesson) => lesson.id === id);
  const { dialogueTail = [], ...metadata } = extra;
  return {
    ...original,
    ...metadata,
    dialogue: [...original.dialogue, ...dialogueTail],
    grammar: { ...original.grammar, examples: original.grammar.examples.slice(0, 2) },
  };
};
const teach = ({ choice, fill, order, ...lesson }) => ({
  ...lesson,
  exercises: [
    { type: 'choice', prompt: choice[0], options: choice[1], answer: choice[2], explanation: choice[3] },
    { type: 'fill', prompt: fill[0], answer: fill[1], explanation: fill[2] },
    { type: 'order', prompt: order[0], words: [...order[1].slice(1), order[1][0]], answer: order[1], explanation: order[2] },
  ],
});

